mapper.select:
SELECT uf.*
FROM user_follow uf
WHERE uf.user_id = #{userId}

    AND uf.create_time < (
        SELECT create_time FROM user_follow WHERE id = #{cursor}
    )

ORDER BY uf.create_time DESC
LIMIT #{pageSize}

select uf.*
from user_follow uf
where uf.follow_id = #{followId}

    and uf.create_time < (
        select create_time from user_follow where id = #{cursor}
    )

order by uf.create_time desc
limit #{pageSize}
